use std::sync::atomic::{AtomicU64, Ordering};
use std::time::{SystemTime, UNIX_EPOCH};

#[derive(Debug, Clone, serde::Serialize, serde::Deserialize)]
pub struct MemoryInput {
    pub content: MemoryContent,
    pub importance: f32,
    pub alias: Option<String>,
    pub tags: Vec<String>,
    pub layer: LayerId,
}

impl MemoryInput {
    pub fn new(content: MemoryContent) -> Self {
        Self {
            content,
            importance: 0.5,
            alias: None,
            tags: Vec::new(),
            layer: LayerId::L1,
        }
    }

    pub fn with_importance(mut self, importance: f32) -> Self {
        self.importance = importance;
        self
    }

    pub fn with_alias(mut self, alias: impl Into<String>) -> Self {
        self.alias = Some(alias.into());
        self
    }

    pub fn with_tags(mut self, tags: Vec<String>) -> Self {
        self.tags = tags;
        self
    }

    pub fn with_layer(mut self, layer: LayerId) -> Self {
        self.layer = layer;
        self
    }
}

static NEXT_MEMORY_ID: AtomicU64 = AtomicU64::new(1);

pub fn generate_memory_id() -> u64 {
    NEXT_MEMORY_ID.fetch_add(1, Ordering::Relaxed)
}

pub fn now_nanos() -> i64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_nanos() as i64
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub enum MemoryContent {
    Fact(Fact),
    Summary(String),
    Fingerprint(u128),
    Embedding(Vec<u8>),
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct Fact {
    pub subject: String,
    pub predicate: String,
    pub object: String,
    pub confidence: f32,
}

impl Fact {
    pub fn new(
        subject: impl Into<String>,
        predicate: impl Into<String>,
        object: impl Into<String>,
    ) -> Self {
        Self {
            subject: subject.into(),
            predicate: predicate.into(),
            object: object.into(),
            confidence: 1.0,
        }
    }

    pub fn with_confidence(mut self, confidence: f32) -> Self {
        self.confidence = confidence.clamp(0.0, 1.0);
        self
    }
}

/// Tracks the origin of a piece of knowledge.
#[derive(Debug, Clone, Copy, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
pub enum KnowledgeSource {
    /// User-provided or external interaction.
    ExternalInput,
    /// Generated by consolidation / merge.
    Consolidation,
    /// Generated by internal rambling / conjecture.
    Rambling,
    /// Inferred by reasoning.
    Inferred,
}

impl Default for KnowledgeSource {
    fn default() -> Self {
        KnowledgeSource::ExternalInput
    }
}

#[derive(Debug, Clone, serde::Serialize, serde::Deserialize)]
pub struct MemoryMeta {
    pub created_at: i64,
    pub last_access: i64,
    pub access_count: u64,
    pub importance: f32,
    pub decay_rate: f32,
    pub attention_score: f32,
    pub layer: LayerId,
    /// Factuality: how well-established this knowledge is [0.0-1.0].
    /// Higher = more cross-verified. Default 0.5 for external input.
    pub factuality: f32,
    /// Abstraction level: Fact≈0.1, merged Summary≈0.5, high-order summary≈0.9.
    pub abstraction_level: f32,
    /// Origin of this knowledge.
    pub source: KnowledgeSource,
    /// If this memory has been overturned, the ID of the replacement.
    /// Query/matching should skip superseded memories.
    pub superseded_by: Option<u64>,
    /// Nanosecond timestamp when this memory was superseded (0 = never).
    pub superseded_at: i64,
}

impl Default for MemoryMeta {
    fn default() -> Self {
        Self {
            created_at: now_nanos(),
            last_access: now_nanos(),
            access_count: 0,
            importance: 0.5,
            decay_rate: 0.1,
            attention_score: 0.0,
            layer: LayerId::L1,
            factuality: 0.5,
            abstraction_level: 0.1,
            source: KnowledgeSource::ExternalInput,
            superseded_by: None,
            superseded_at: 0,
        }
    }
}

impl MemoryMeta {
    pub fn record_access(&mut self) {
        self.last_access = now_nanos();
        self.access_count += 1;
    }

    pub fn recency_score(&self, decay_lambda: f32) -> f32 {
        let elapsed = (now_nanos() - self.last_access).max(1) as f64;
        (-decay_lambda as f64 * elapsed / 1_000_000_000.0_f64).exp() as f32
    }

    pub fn attention_lru_score(&self, alpha: f32, beta: f32, decay_lambda: f32) -> f32 {
        let recency = self.recency_score(decay_lambda);
        let attention = (1.0 + self.access_count as f32).ln();
        alpha * recency + beta * attention
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, serde::Serialize, serde::Deserialize)]
pub enum LayerId {
    L1,
    L2,
    L3,
    ColdMerged,
}

impl LayerId {
    pub fn as_str(&self) -> &'static str {
        match self {
            LayerId::L1 => "l1",
            LayerId::L2 => "l2",
            LayerId::L3 => "l3",
            LayerId::ColdMerged => "cold_merged",
        }
    }
}

#[derive(Debug, Clone, serde::Serialize, serde::Deserialize)]
pub struct Memory {
    pub id: u64,
    pub content: MemoryContent,
    pub metadata: MemoryMeta,
    pub alias: Option<String>,
    pub tags: Vec<String>,
}

impl Memory {
    pub fn new(content: MemoryContent) -> Self {
        Self {
            id: generate_memory_id(),
            content,
            metadata: MemoryMeta::default(),
            alias: None,
            tags: Vec::new(),
        }
    }

    pub fn with_importance(mut self, importance: f32) -> Self {
        self.metadata.importance = importance.clamp(0.0, 1.0);
        self
    }

    pub fn with_layer(mut self, layer: LayerId) -> Self {
        self.metadata.layer = layer;
        self
    }

    pub fn record_access(&mut self) {
        self.metadata.record_access();
    }

    pub fn attention_lru_score(&self, alpha: f32, beta: f32, decay_lambda: f32) -> f32 {
        self.metadata.attention_lru_score(alpha, beta, decay_lambda)
    }
}

#[derive(Debug, Clone)]
pub struct Query {
    pub key: Option<u64>,
    pub text: Option<String>,
    pub alias: Option<String>,
    pub embedding: Option<Vec<f32>>,
    pub top_k: usize,
    /// Optional time range filter (nanoseconds since epoch).
    pub time_after: Option<i64>,
    pub time_before: Option<i64>,
    /// Minimum importance threshold [0.0, 1.0].
    pub min_importance: Option<f32>,
    /// Maximum importance threshold [0.0, 1.0].
    pub max_importance: Option<f32>,
    /// Tags that must all be present (AND).
    pub tags_include: Option<Vec<String>>,
    /// Tags that must all be absent.
    pub tags_exclude: Option<Vec<String>>,
    /// Filter by specific layer(s).
    pub layers: Option<Vec<LayerId>>,
}

impl Query {
    pub fn by_id(id: u64) -> Self {
        Self {
            key: Some(id),
            text: None,
            alias: None,
            embedding: None,
            top_k: 1,
            time_after: None,
            time_before: None,
            min_importance: None,
            max_importance: None,
            tags_include: None,
            tags_exclude: None,
            layers: None,
        }
    }

    pub fn by_text(text: impl Into<String>) -> Self {
        Self {
            key: None,
            text: Some(text.into()),
            alias: None,
            embedding: None,
            top_k: 5,
            time_after: None,
            time_before: None,
            min_importance: None,
            max_importance: None,
            tags_include: None,
            tags_exclude: None,
            layers: None,
        }
    }

    pub fn by_alias(alias: impl Into<String>) -> Self {
        Self {
            key: None,
            text: None,
            alias: Some(alias.into()),
            embedding: None,
            top_k: 5,
            time_after: None,
            time_before: None,
            min_importance: None,
            max_importance: None,
            tags_include: None,
            tags_exclude: None,
            layers: None,
        }
    }

    pub fn by_embedding(embedding: Vec<f32>) -> Self {
        Self {
            key: None,
            text: None,
            alias: None,
            embedding: Some(embedding),
            top_k: 5,
            time_after: None,
            time_before: None,
            min_importance: None,
            max_importance: None,
            tags_include: None,
            tags_exclude: None,
            layers: None,
        }
    }

    pub fn hash_key(&self) -> Option<u64> {
        self.key
    }

    pub fn text(&self) -> Option<&str> {
        self.text.as_deref()
    }

    pub fn alias(&self) -> Option<&str> {
        self.alias.as_deref()
    }

    pub fn embedding(&self) -> Option<&[f32]> {
        self.embedding.as_deref()
    }

    // --- Builder-style filter methods ---

    pub fn with_time_range(mut self, after: i64, before: i64) -> Self {
        self.time_after = Some(after);
        self.time_before = Some(before);
        self
    }

    pub fn with_time_after(mut self, after: i64) -> Self {
        self.time_after = Some(after);
        self
    }

    pub fn with_time_before(mut self, before: i64) -> Self {
        self.time_before = Some(before);
        self
    }

    pub fn with_min_importance(mut self, min: f32) -> Self {
        self.min_importance = Some(min.clamp(0.0, 1.0));
        self
    }

    pub fn with_max_importance(mut self, max: f32) -> Self {
        self.max_importance = Some(max.clamp(0.0, 1.0));
        self
    }

    pub fn with_tags_include(mut self, tags: Vec<String>) -> Self {
        self.tags_include = Some(tags);
        self
    }

    pub fn with_tags_exclude(mut self, tags: Vec<String>) -> Self {
        self.tags_exclude = Some(tags);
        self
    }

    pub fn with_layers(mut self, layers: Vec<LayerId>) -> Self {
        self.layers = Some(layers);
        self
    }

    /// Check whether a memory matches all filter criteria in this query.
    /// Automatically skips memories that have been superseded (overturned).
    pub fn matches(&self, memory: &Memory) -> bool {
        if memory.metadata.superseded_by.is_some() {
            return false;
        }
        if let Some(after) = self.time_after {
            if memory.metadata.created_at < after {
                return false;
            }
        }
        if let Some(before) = self.time_before {
            if memory.metadata.created_at > before {
                return false;
            }
        }
        if let Some(min_imp) = self.min_importance {
            if memory.metadata.importance < min_imp {
                return false;
            }
        }
        if let Some(max_imp) = self.max_importance {
            if memory.metadata.importance > max_imp {
                return false;
            }
        }
        if let Some(ref include) = self.tags_include {
            for tag in include {
                if !memory.tags.contains(tag) {
                    return false;
                }
            }
        }
        if let Some(ref exclude) = self.tags_exclude {
            for tag in exclude {
                if memory.tags.contains(tag) {
                    return false;
                }
            }
        }
        if let Some(ref layers) = self.layers {
            if !layers.contains(&memory.metadata.layer) {
                return false;
            }
        }
        true
    }
}
